pub fn project_tests_result(total: i64, failed: i64) -> i32 {
    let passed = total - failed;
    let said = match failed == 0 {
        true => "ok",
        false => "FAILED",
    };
    println!("\ntest result: {}. {} passed; {} failed", said, passed, failed);
    match failed == 0 {
        true => 0,
        false => 1,
    }
}

